363:         // ------------------------------------------------------------------ update
364: 
365:         private void Update()
366:         {
367:             if (!_live || _frozen) return;
368:             float dt = Time.deltaTime;
369:             UpdateFlash(dt);
370: 
371:             if (_script != null) UpdateScene(dt);
372:             else UpdateIdle(dt);
