374: 
375:         private void UpdateScene(float dt)
376:         {
377:             if (_suspendedAtShot) return; // the frozen shot — the window's dread
378: 
379:             if (!_stepEntered) EnterStep();
380:             Step s = _script[_stepIx];
381: 
382:             // Motion (real frame time — cosmetic): formations speak the scene's territory,
383:             // the ball travels its routed target, tempo scales everything.
384:             float speed = 1f + s.Tempo * 1.6f;
385:             _sceneTerr = Mathf.SmoothDamp(_sceneTerr, s.Terr, ref _sceneTerrVel, 0.45f / speed);
386:             LastTerritoryX = _sceneTerr;
387:             MoveActors(_sceneTerr, speed, s.Chase, s.AtkPicked);
388: 
389:             Vector2 target = _routeDotIx >= 0 ? DotPos(_routeDotHome, _routeDotIx) : _stepBallLocal;
390:             _ballPos = Vector2.SmoothDamp(_ballPos, target, ref _ballVel, ballDamp / speed);
391:             ApplyPositions();
392: 
393:             // Story time (scaled — batch tests fast-forward through here by shrinking the
394:             // effective duration, exactly like SeatedHold does with TimeScaleOverride).
395:             _stepT += dt;
396:             if (_stepT < s.Dur * Mathf.Max(0f, timeScale)) return;
397: 
398:             CompleteStep(s);
399:             if (_suspendedAtShot) return; // MkSuspend holds ON its step until resumed
400: 
401:             _stepIx++;
402:             _stepT = 0f;
403:             _stepEntered = false;
404:             if (_stepIx >= _script.Length)
405:             {
406:                 _script = null;
407:                 FireReveal(); // scenes with no explicit payoff reveal at their end
408:                 Action done = _onSceneComplete;
409:                 _onGoalPlayed = null;
410:                 _onReveal = null;
411:                 _onSceneComplete = null;
412:                 done?.Invoke();
413:             }
414:         }
415: 
416:         /// <summary>Resolves the step's ball routing against the ACTUAL actors — the move must
417:         /// read as the attacking team passing it around, never a ball flying to nobody.</summary>
418:         private void EnterStep()
419:         {
420:             _stepEntered = true;
421:             Step s = _script[_stepIx];
422:             bool atkHome = s.AtkPicked == _homeAttacksRight;
423:             _routeDotIx = -1;
424: 
425:             switch (s.Route)
426:             {
427:                 case RoutePass:
428:                 {
429:                     Vector2 want = ToLocal(s.Ball);
430:                     int ix = NearestOutfield(atkHome, want, exclude: BallCarriedBy(atkHome) ? _carrierIx : -1);
431:                     _routeDotIx = ix;
432:                     _routeDotHome = atkHome;
433:                     // Off-ball: teammates near the move make short forward runs, not static jitter.
434:                     ForwardRuns(atkHome, s.AtkPicked ? 1f : -1f);
435:                     break;
436:                 }
437:                 case RouteBackLine:
438:                 {
439:                     Vector2 want = ToLocal(s.Ball);
440:                     _routeDotIx = NearestBackLine(!atkHome, want);
441:                     _routeDotHome = !atkHome;
442:                     break;
443:                 }
444:                 case RouteShot:
445:                 {
446:                     // Aim at the corner AWAY from the defending keeper — a shot, not a pass.
447:                     Vector2 authored = s.Ball;
448:                     bool rightGoal = authored.x > 0.5f;
449:                     Vector2 keeper = rightGoal
450:                         ? (_homeAttacksRight ? _akPos : _hkPos)
451:                         : (_homeAttacksRight ? _hkPos : _akPos);
452:                     authored.y = keeper.y > 0f ? 0.42f : 0.58f;
453:                     _stepBallLocal = ToLocal(authored);
454:                     break;
455:                 }
456:                 case RouteKickoff:
457:                 default:
458:                     _stepBallLocal = ToLocal(s.Ball);
459:                     break;
460:             }
461:         }
462: 
463:         /// <summary>End-of-step bookkeeping: markers fire, and possession follows the story so
464:         /// the idle loop resumes from a coherent carrier.</summary>
465:         private void CompleteStep(Step s)
466:         {
467:             switch (s.Marker)
468:             {
469:                 case MkGoal:
470:                     FlashGoal(right: s.Ball.x > 0.5f, strong: s.Goal.Commits);
471:                     _onGoalPlayed?.Invoke(s.Goal);
472:                     FireReveal(); // the net ripple IS the beat's payoff
473:                     break;
474:                 case MkSuspend:
475:                     _suspendedAtShot = true;
476:                     break;
477:                 case MkSave:
478:                     KeeperLunge();
479:                     FireReveal(); // the save IS the near-miss payoff
480:                     break;
481:                 case MkVoid:
482:                     ApplyVoidTint();
483:                     break;
484:             }
485: 
486:             switch (s.Route)
487:             {
488:                 case RoutePass:
489:                 case RouteBackLine:
490:                     if (_routeDotIx >= 0)
491:                     {
492:                         _carrierHome = _routeDotHome;
493:                         _carrierIx = _routeDotIx;
494:                     }
495:                     break;
496:                 case RouteKickoff:
497:                     // The side that just conceded collects at the center spot.
498:                     _carrierHome = s.AtkPicked != _homeAttacksRight;
499:                     _carrierIx = 4;
500:                     break;
501:             }
502:         }
503: 
504:         private void FireReveal()
505:         {
506:             if (_revealFired) return;
507:             _revealFired = true;
508:             _onReveal?.Invoke();
509:         }
