511:         private void UpdateIdle(float dt)
512:         {
513:             _pulse = Mathf.MoveTowards(_pulse, 0f, dt / Mathf.Max(0.01f, pulseDecay));
514:             _urgency = Mathf.MoveTowards(_urgency, 0f, dt * 0.5f);
515: 
516:             // Territory: the honest prob, plus the decaying beat impulse. The picked side
517:             // attacks right, so territoryX already speaks the pick's language.
518:             float terr = PitchLayout.TerritoryX(_prob) + _pulse * _pulseSign * pulseKick;
519:             terr = Mathf.Clamp(terr, 0.08f, 0.92f);
520:             _sceneTerr = terr; // scenes resume smoothly from wherever idle left the shape
521:             LastTerritoryX = terr;
522: 
523:             float speed = 1f + _urgency * 1.4f;
524:             MoveActors(terr, speed, chase: false, atkPicked: terr >= 0.5f);
525: 
526:             // Sticky possession: the carrier keeps it, passes go to TEAMMATES, and turnovers
527:             // are visible interceptions. Long-run possession share restates the live prob
528:             // (allowed: it repeats revealed state) — nothing here ever implies a goal.
529:             if (Time.time >= _nextPassAt)
530:             {
531:                 _nextPassAt = Time.time + NextPassDelay() / speed;
532:                 float share = Mathf.Lerp(0.25f, 0.75f, _prob); // picked side's possession target
533:                 bool carrierPicked = _carrierHome == _homeAttacksRight;
534:                 float keep = carrierPicked
535:                     ? Mathf.Lerp(0.55f, 0.92f, share)
536:                     : Mathf.Lerp(0.55f, 0.92f, 1f - share);
537:                 if (_rng.NextDouble() < keep) PassToTeammate(terr);
538:                 else TurnoverAtBall();
539:             }
540: 
541:             _ballPos = Vector2.SmoothDamp(_ballPos, DotPos(_carrierHome, _carrierIx), ref _ballVel, ballDamp / speed);
542:             ApplyPositions();
543:         }
544: 
545:         /// <summary>A pass within the team in possession: best of three candidates, preferring
546:         /// a comfortable pass length and progress toward the territory point.</summary>
547:         private void PassToTeammate(float terr)
548:         {
549:             Vector2 from = DotPos(_carrierHome, _carrierIx);
550:             float terrX = (terr - 0.5f) * (_w - Pad * 2f);
551:             int best = -1;
552:             float bestScore = float.NegativeInfinity;
553:             for (int tries = 0; tries < 3; tries++)
554:             {
555:                 int c = _rng.Next(PitchLayout.OutfieldPerTeam);
556:                 if (c == _carrierIx) continue;
557:                 Vector2 p = DotPos(_carrierHome, c);
558:                 float dist = Vector2.Distance(from, p);
559:                 if (dist < 24f) continue; // no toe-pokes to a dot standing on the ball
560:                 float lengthScore = -Mathf.Abs(dist - 120f) * 0.01f;          // comfortable pass
561:                 float progressScore = -Mathf.Abs(p.x - terrX) * 0.008f;       // toward the action
562:                 float score = lengthScore + progressScore;
563:                 if (score > bestScore) { bestScore = score; best = c; }
564:             }
565:             if (best >= 0) _carrierIx = best;
566:         }
567: 
568:         /// <summary>A visible turnover: the nearest opponent steps INTO the ball and takes it —
569:         /// possession flips because somebody won it, not because the script blinked.</summary>
570:         private void TurnoverAtBall()
571:         {
572:             bool interceptorHome = !_carrierHome;
573:             int ix = NearestOutfield(interceptorHome, _ballPos, exclude: -1);
574:             ref Vector2 vel = ref (interceptorHome ? ref _homeVel[ix] : ref _awayVel[ix]);
575:             Vector2 toBall = _ballPos - DotPos(interceptorHome, ix);
576:             vel += toBall.normalized * Mathf.Min(toBall.magnitude * 4f, 220f);
577:             _carrierHome = interceptorHome;
578:             _carrierIx = ix;
579:         }
580: 
581:         /// <summary>Formation motion shared by idle and scenes (M-T3.1): the attacking shape
582:         /// pushes up while the DEFENDING team drops into a compact block; on chase steps the
583:         /// two defenders nearest the ball hunt the carrier instead of holding shape.</summary>
584:         private void MoveActors(float terr, float speed, bool chase, bool atkPicked)
585:         {
586:             float bias = (terr - 0.5f) * 2f; // [-1, 1] toward the right goal (picked frame)
587:             float damp = dotDamp / speed;
588: 
589:             // Per-team posture: positive = on the front foot, negative = under siege.
590:             float homeAtk = _homeAttacksRight ? bias : -bias;
591:             float awayAtk = -homeAtk;
592:             float homeCompact = Mathf.Clamp01(-homeAtk) * 0.8f;
593:             float awayCompact = Mathf.Clamp01(-awayAtk) * 0.8f;
594: 
595:             bool chaseHome = chase && atkPicked != _homeAttacksRight; // defenders chase
596:             int chase1 = -1, chase2 = -1;
597:             if (chase) FindNearestTwo(chaseHome, _ballPos, out chase1, out chase2);
598: 
599:             for (int i = 0; i < PitchLayout.OutfieldPerTeam; i++)
600:             {
601:                 Vector2 ht = chaseHome && (i == chase1 || i == chase2)
602:                     ? _ballPos + new Vector2(_homeAttacksRight ? -26f : 26f, i == chase1 ? 12f : -14f)
603:                     : ToLocal(PitchLayout.FormationSlot(i, _homeAttacksRight, homeAtk, homeCompact)) + _homeNoise[i];
604:                 Vector2 at = !chaseHome && chase && (i == chase1 || i == chase2)
605:                     ? _ballPos + new Vector2(_homeAttacksRight ? 26f : -26f, i == chase1 ? 12f : -14f)
606:                     : ToLocal(PitchLayout.FormationSlot(i, !_homeAttacksRight, awayAtk, awayCompact)) + _awayNoise[i];
607:                 _homePos[i] = Vector2.SmoothDamp(_homePos[i], ht, ref _homeVel[i], damp);
608:                 _awayPos[i] = Vector2.SmoothDamp(_awayPos[i], at, ref _awayVel[i], damp);
609:             }
610:             _hkPos = Vector2.SmoothDamp(_hkPos, ToLocal(PitchLayout.Keeper(_homeAttacksRight)), ref _hkVel, dotDamp);
611:             _akPos = Vector2.SmoothDamp(_akPos, ToLocal(PitchLayout.Keeper(!_homeAttacksRight)), ref _akVel, dotDamp);
612:         }
