211:         private IEnumerator RunChannel()
212:         {
213:             while (true)
214:             {
215:                 if (director == null || director.Run == null) { yield return null; continue; }
216: 
217:                 switch (director.Run.Phase)
218:                 {
219:                     case Phase.Sweat:
220:                         yield return PresentRound();
221:                         break;
222: 
223:                     case Phase.Betting:
224:                         RenderIdle("betting", "PLACE YOUR BETS",
225:                             "the book is open on the laptop", moneyIdle: true);
226:                         yield return null;
227:                         break;
228: 
229:                     case Phase.Shop:
230:                         RenderIdle("shop", "SHOP OPEN",
231:                             "gear up at the laptop, then the next round", moneyIdle: true);
232:                         yield return null;
233:                         break;
234: 
235:                     case Phase.RunWon:
236:                     case Phase.RunLost:
237:                         RenderRunOver();
238:                         yield return null;
239:                         break;
240: 
241:                     default: // Settlement is transient (zero-ticket locks settle inside the director)
242:                         yield return null;
243:                         break;
244:                 }
245:             }
246:         }
247: 
248:         /// <summary>The locked round, serially: ticket card → sweat → per-ticket beat, for each ticket,
249:         /// then FinishAndSettle and the settle card. The director owns the index; we own the ceremony.</summary>
250:         private IEnumerator PresentRound()
251:         {
252:             _idleKey = null;
253: 
254:             while (director.Run.Phase == Phase.Sweat && director.CurrentSession != null)
255:             {
256:                 _session = director.CurrentSession;
257:                 _ticket = director.CurrentTicket;
258: 
259:                 yield return TicketCardBeat();
260:                 yield return PlaySweat();
261:                 yield return SettlementBeat();
262: 
263:                 if (!director.AdvanceSweat()) break;
264:             }
265: 
266:             if (director.Run.Phase == Phase.Sweat)
267:             {
268:                 director.FinishAndSettle();
269:                 yield return SettleCardBeat();
270:             }
271:         }
