273:         private IEnumerator TicketCardBeat()
274:         {
275:             ResetForNewSession(); // clears floods/dim/static, resets the light, shows the attract
276:             _tAttract.text = "SIT TO WATCH THE SWEAT";
277:             _tAttract.color = new Color(phosphorGreen.r, phosphorGreen.g, phosphorGreen.b, 1f);
278:             RenderTicketCard();
279: 
280:             yield return WaitSeated();
281:             _tAttract.enabled = false;
282:             yield return SeatedHold(ticketCardDuration * 1000f);
283:         }
