285:         private IEnumerator PlaySweat()
286:         {
287:             RenderPregame();
288:             int lastLeg = _ticket.Legs.Count - 1;
289: 
290:             while (_session != null && !_session.IsComplete)
291:             {
292:                 yield return WaitSeated();            // step ONLY while seated
293:                 if (_session.IsComplete) break;      // e.g. cashed out while we waited
294: 
295:                 if (!_session.MoveNext(out DramaEvent evt)) break;
296:                 _eventsEmitted++;
297:                 RenderEvent(evt);
298: 
299:                 if (_stage != null)
300:                 {
301:                     // M-T3: the scenes own pacing AND the resolution ceremony.
302:                     yield return TheaterBeat(evt);
303:                     continue;
304:                 }
305: 
306:                 bool onFinalLeg = evt.LegIndex == lastLeg;
307:                 if (evt.Type == DramaEventType.LegFinal)
308:                     yield return ResolveBeat(evt);
309: 
310:                 // The pending-loss window (charm expansion): a dead leg suspended the session
311:                 // while a save is held — the drama freezes on the player's timed decision.
312:                 if (_session.HasPendingLoss)
313:                     yield return PendingWindowBeat();
314: 
315:                 if (_session.IsComplete) break;
316:                 yield return SeatedHold(PacingFor(evt, onFinalLeg));
317:             }
318:         }
319: 
320:         // ---------------------------------------------------------------- theater beats (M-T3)
321: 
322:         /// <summary>One beat as theater: non-final beats play their resolved scene (the scene's
323:         /// duration IS the pacing); a LegFinal plays the final whistle sequence with the
324:         /// ledger's stoppage-time plan; a pending loss suspends the kill scene at the shot
325:         /// mid-flight, holds through the save window, and resumes with the continuation chosen
326:         /// from the FINAL ticket-local grade (never WinProbAfter).</summary>
327:         private IEnumerator TheaterBeat(DramaEvent evt)
328:         {
329:             Leg leg = _ticket.Legs[evt.LegIndex];
330:             _stage.timeScale = Mathf.Max(0f, TimeScaleOverride);
331: 
332:             SuspendMarket(); // the engine repriced at MoveNext — no price until the reveal
333: 
334:             if (evt.Type != DramaEventType.LegFinal)
335:             {
336:                 SceneSpec spec = _choreo.ResolveBeat(evt, _lastBeatUp, _ledger);
337:                 _stage.PlayScene(spec, OnGoalPlayed, RevealBeatChrome, null);
338:                 yield return WaitSceneDone();
339:                 if (_session.IsComplete) yield break; // cashed out mid-scene
340:                 yield return SeatedHold(interSceneGapMs); // idle filler ≤1s between scenes
341:                 yield break;
342:             }
343: 
344:             if (_session.HasPendingLoss)
345:             {
346:                 // The clippable moment: buildup → the shot freezes mid-flight → the prompt.
347:                 // The chrome still speaks the PRE-KILL state (the honest displayed value the
348:                 // whistle rolls against) — the 0% never shows before the story resolves.
349:                 _stage.SuspendKillShot(ScenePlaybook.VariantFor(evt.Step));
350:                 while (_stage.ScenePlaying && !_stage.SuspendedAtShot) yield return null;
351:                 yield return PendingWindowBeat();
352: 
353:                 LegGrade grade = leg.IsVoided ? LegGrade.Voided
354:                     : leg.GradesWon ? LegGrade.Won : LegGrade.Lost;
355:                 ScoreLedger.FinalPlan plan = _ledger.PlanFinal(grade);
356:                 _stage.ResumeSuspended(plan, OnGoalPlayed, null);
357:                 yield return WaitSceneDone();
358:                 yield return FinalSlam(evt, grade);
359:             }
360:             else
361:             {
362:                 LegGrade grade = leg.IsVoided ? LegGrade.Voided
363:                     : leg.GradesWon ? LegGrade.Won : LegGrade.Lost;
364:                 ScoreLedger.FinalPlan plan = _ledger.PlanFinal(grade);
365:                 SceneSpec spec = _choreo.ResolveFinal(grade, evt.Step);
366:                 _stage.PlayFinalScene(spec, plan, OnGoalPlayed, null);
367:                 yield return WaitSceneDone();
368:                 yield return FinalSlam(evt, grade);
369:             }
370:         }
