372:         /// <summary>Waits out the active scene. Seating freezes the stage (the scene stalls, so
373:         /// this stalls with it); a cash-out abandons the scene — the gold flood takes the screen.</summary>
374:         private IEnumerator WaitSceneDone()
375:         {
376:             while (_stage != null && _stage.ScenePlaying)
377:             {
378:                 if (_ticket != null && _ticket.State == TicketState.CashedOut)
379:                 {
380:                     _stage.CancelScene();
381:                     yield break;
382:                 }
383:                 yield return null;
384:             }
385:         }
