387:         /// <summary>The GREEN/DEAD slam, fired as the final scene completes (TvLight sync) —
388:         /// which is also the final's REVEAL moment: only now do the clock read FT and the bar
389:         /// snap to the outcome. The VOID path already spoke inside the pending window (the
390:         /// slip ceremony), and a voided match keeps its pre-kill bar — 0/1 never applied.</summary>
391:         private IEnumerator FinalSlam(DramaEvent evt, LegGrade grade)
392:         {
393:             _tClock.text = "FT";
394:             if (grade == LegGrade.Won)
395:             {
396:                 _probTarget = 1f;
397:                 _tWinPct.text = "WIN 100%";
398:             }
399:             else if (grade == LegGrade.Lost)
400:             {
401:                 _probTarget = 0f;
402:                 _tWinPct.text = "WIN 0%";
403:             }
404: 
405:             _resolvedThrough = evt.LegIndex + 1;
406:             UpdateSlipStrip(evt.LegIndex + 1);
407:             int k = evt.LegIndex + 1;
408:             if (grade == LegGrade.Won) yield return GreenLegBeat(k);
409:             else if (grade == LegGrade.Lost) yield return DeadLegBeat(k);
410:             ReopenMarket(); // between legs (or at the end) the fresh price may speak again
411:         }
