414:         /// stands), the scorebug speaks, VAR gets its line. The ONLY score path (goal-playback
415:         /// invariant: the board can never move without a goal on the pitch).</summary>
416:         private void OnGoalPlayed(ScoreLedger.StagedGoal goal)
417:         {
418:             _ledger.CompleteGoal(goal);
419:             if (_ticket != null && _stageLeg >= 0 && _stageLeg < _ticket.Legs.Count)
