429:         /// <summary>The pending-loss window (charm expansion): [M] plays a Mulligan (leg voided,
430:         /// sweat resumes), [R] plays the Ref's Whistle (the call goes to review at the odds you
431:         /// were living on — overturned it STANDS at full odds, confirmed it dies), [N] declines.
432:         /// The drama holds as long as the decision does — the pause IS the moment. Without a
433:         /// keyboard (batch tests) the window declines immediately, so autoplay never hangs.</summary>
434:         private IEnumerator PendingWindowBeat()
435:         {
436:             if (Keyboard.current == null)
437:             {
438:                 _session.DeclinePendingLoss();
439:                 yield break;
440:             }
441: 
442:             bool canM = director.Run.OwnsConsumable("mulligan_slip") && _session.CanMulliganPendingLoss;
443:             bool canR = director.Run.OwnsConsumable("refs_whistle");
444:             string verbs = (canM ? "[M] MULLIGAN   ·   " : "")
445:                 + (canR ? $"[R] SEND TO REVIEW ({Mathf.RoundToInt((float)(_session.PendingLossProbBefore * 100))}%)   ·   " : "");
446:             _tCashOut.enabled = true;
447:             _tCashOut.color = new Color(gold.r, gold.g, gold.b, 1f); // the prompt is actionable — gold
448:             _tCashOut.text = verbs + "[N] LET IT DIE";
449: 
760:             SetAlpha(_goldFlood, 0f);
761:             SetAlpha(_dimOverlay, 0f);
762:             SetRawAlpha(_staticNoise, 0f);
763:             _tCashOut.enabled = false;
764:             _tBigAmount.text = string.Empty;
765:             _tLeg.text = string.Empty;
766:             _tClock.text = string.Empty;
767:             _tMatchup.text = string.Empty;
768:             _tRecords.text = string.Empty;
769:             _tSlipStrip.text = string.Empty;
770:             _tWinPct.text = string.Empty;
771:             _tFlavor.text = string.Empty;
772:         }
