774:         private void RenderEvent(DramaEvent evt)
775:         {
776:             Leg leg = _ticket.Legs[evt.LegIndex];
777: 
778:             _tRecords.text = RecordsLine(leg);
779:             _tLeg.text = $"LEG {evt.LegIndex + 1}/{_ticket.Legs.Count}";
780: 
781:             if (evt.LegIndex != _flavorLegSeen)
782:             {
783:                 _flavorLegSeen = evt.LegIndex;
784:                 _prevProb = leg.TrueProb; // pre-event anchor for this leg's first beat
785:             }
786:             string flavor = SweatFlavor.For(evt, leg, _prevProb);
787:             _prevProb = evt.WinProbAfter;
788: 
789:             // The stage speaks the same beat (model owns the direction rule — one authority).
790:             _lastBeatUp = _presModel.RecordBeat(evt, leg);
791:             if (_stage != null)
792:             {
793:                 // Causal reveal (M-T3.1): identity chrome may update now, but the win-prob,
794:                 // WIN %, flavor, and clock are STASHED — they land at the scene's payoff
795:                 // (RevealBeatChrome / FinalSlam), never before the pitch has shown the story.
796:                 _pendingProb = (float)evt.WinProbAfter;
797:                 _pendingFlavor = flavor;
798:                 _pendingClock = SweatFlavor.Clock(evt);
799: 
800:                 if (evt.LegIndex != _stageLeg) BeginStageLeg(evt.LegIndex, leg);
801:                 _stage.SetLiveProb((float)evt.WinProbAfter);
802:                 UpdateScorebug(leg); // colored identity + running score (M-T3 scorebug)
803:             }
804:             else
805:             {
806:                 _tClock.text = SweatFlavor.Clock(evt);
807:                 _tFlavor.color = flavorColor;
808:                 _tFlavor.text = flavor;
809:                 _flavorScale = 1.12f; // punch
810:                 _probTarget = (float)evt.WinProbAfter;
811:                 _tWinPct.text = $"WIN {Mathf.RoundToInt(_probTarget * 100f)}%";
812:                 _tMatchup.text = MatchupLine(leg);
813:                 UpdateCashOutLabel();
814:             }
815: 
816:             _tAttract.enabled = false;
817:             UpdateSlipStrip(evt.LegIndex);
818:         }
