820:         /// <summary>The beat's payoff moment on the stage: NOW the chrome may speak — the
821:         /// win-prob bar moves, the flavor line lands, the clock ticks, the market re-opens
822:         /// at the fresh price. Fired by the scene's onReveal (goal / save / scene end).</summary>
823:         private void RevealBeatChrome()
824:         {
825:             _probTarget = _pendingProb;
826:             _tWinPct.text = $"WIN {Mathf.RoundToInt(_probTarget * 100f)}%";
827:             _tClock.text = _pendingClock;
828:             _tFlavor.color = flavorColor;
829:             _tFlavor.text = _pendingFlavor;
830:             _flavorScale = 1.12f;
831:             ReopenMarket();
832:         }
833: 
834:         /// <summary>While a scene plays, the book suspends the market (M-T3.1): the engine has
835:         /// already repriced, so the only honest options are the new price (a spoiler) or no
836:         /// price. Real books suspend on a dangerous attack — so does ours.</summary>
837:         private void SuspendMarket()
838:         {
839:             _marketSuspended = true;
840:             bool offerExists = _session != null && !_session.IsComplete
841:                 && _eventsEmitted >= 1 && _session.CashOutOffer().HasValue;
842:             if (offerExists)
843:             {
844:                 // Neutral pending-gray (the slip strip's not-yet color) — NOT cyan: in sweat
845:                 // semantics cyan is reserved for VOID (design/08), and a suspended market at
846:                 // peak tension must never read as a voided leg.
847:                 _tCashOut.enabled = true;
848:                 _tCashOut.color = new Color(0.48f, 0.53f, 0.56f, 1f);
849:                 _tCashOut.text = "MARKET SUSPENDED";

500:             {
501:                 case TicketState.CashedOut:
502:                     yield return ScaledWait(cashOutFloodDuration); // the gold flood (fired on accept) breathes
503:                     break;
504:                 case TicketState.Lost:
505:                     yield return TicketDeadBeat();
506:                     break;
507:                 default: // still Open, grades won -> the payout moment
508:                     yield return WinBeat();
509:                     break;
510:             }
511:         }
