557:         /// <summary>Kicks the stage off for a leg: model-owned team colors (deterministic,
558:         /// non-reserved pool), the picked side attacking right, territory opening at TrueProb.
559:         /// New leg = new match: the score ledger resets and the scorebug re-speaks.</summary>
560:         private void BeginStageLeg(int legIndex, Leg leg)
561:         {
562:             if (_stage == null) return;
563:             _stageLeg = legIndex;
564:             _ledger.ResetForLeg();
565:             (uint home, uint away) = TheaterPalette.TeamColors(leg.Matchup.Home.Name, leg.Matchup.Away.Name);
566:             _stage.Show(true);
567:             _stage.BeginLeg(TheaterStage.FromRgb(home), TheaterStage.FromRgb(away),
568:                 pickedIsHome: leg.Side == Side.Home, openingProb: (float)leg.TrueProb);
569:             UpdateScorebug(leg);
570:         }
