572:         /// <summary>The theater scorebug (M-T3, playtest #10 finding #2 pulled forward from
573:         /// chrome v2): team names IN their dot colors so the stage is instantly attributable,
574:         /// the running synthesized score between them, the picked side marked. Away @ home
575:         /// order, matching the slate's convention everywhere else.</summary>
576:         private void UpdateScorebug(Leg leg)
577:         {
578:             if (_tMatchup == null) return;
